# refresh_prices.ps1
# ------------------------------------------------------------------
# Dashboard price snapshot: monthly refresh + auto deploy.
#
# Why: the dashboard metal / feed / livestock / FX charts all read
#      price_snapshot.json on the server. That file is pre-generated by the
#      Flask price endpoints. Nobody rebuilt it after 2026-09-06, so the
#      dashboard had no new months from 2026-10 on.
#
# Steps:
#   1) collect livestock monthly data (collect_livestock.py --seed-real --incremental)
#   2) fetch metal/feed/FX + pack snapshot (build_price_snapshot.py)
#   3) back up the remote snapshot, upload the new one
#   4) verify the live API month, write a status file
#
# Run by Windows Task Scheduler (install_price_task.ps1), or manually:
#   powershell -ExecutionPolicy Bypass -File .\refresh_prices.ps1
#
# NOTE: keep this file ASCII-only. PowerShell 5.1 reads BOM-less .ps1 as ANSI
#       and any UTF-8 Chinese character breaks the parser.
# ------------------------------------------------------------------
$ErrorActionPreference = 'Continue'

$Root      = 'C:\gs-project'
$Server    = 'ubuntu@124.156.134.135'
$Key       = "$HOME/.ssh/agi_pm_deploy"
$RemoteDir = '/home/ubuntu/node-backend/data/files'
$OutDir    = Join-Path $Root '_snapshot_out'
$OutFile   = Join-Path $OutDir 'price_snapshot.json'
$LogFile   = Join-Path $OutDir 'refresh_prices.log'
$Py        = 'python'

if (-not (Test-Path $OutDir)) { New-Item -ItemType Directory -Path $OutDir -Force | Out-Null }

function Log([string]$msg) {
  $line = ('{0}  {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg)
  Add-Content -Path $LogFile -Value $line -Encoding utf8
  Write-Host $line
}

Log '========== refresh_prices start =========='
Set-Location $Root

# 1) livestock monthly update
Log '[1/4] collect_livestock --seed-real --incremental'
& $Py 'collect_livestock.py' '--seed-real' '--incremental' 2>&1 | Tee-Object -FilePath $LogFile -Append | Out-Null
if ($LASTEXITCODE -ne 0) { Log "WARN: collect_livestock exit=$LASTEXITCODE (continue with cached data)" }

# 2) build snapshot
Log '[2/4] build_price_snapshot'
& $Py 'build_price_snapshot.py' '--out' $OutFile 2>&1 | Tee-Object -FilePath $LogFile -Append | Out-Null
if ($LASTEXITCODE -ne 0) { Log "ERROR: build_price_snapshot exit=$LASTEXITCODE -- abort"; exit 2 }
if (-not (Test-Path $OutFile)) { Log 'ERROR: snapshot file not produced -- abort'; exit 2 }

$size = (Get-Item $OutFile).Length
Log ('[2/4] snapshot size = {0} bytes' -f $size)

# 3) backup + upload
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
Log "[3/4] backup remote snapshot and upload ($stamp)"
& ssh -i $Key -o StrictHostKeyChecking=no -o BatchMode=yes $Server "cd $RemoteDir && (cp -n price_snapshot.json price_snapshot.json.bak-$stamp || true) && ls -1t price_snapshot.json.bak-* 2>/dev/null | tail -n +13 | xargs -r rm -f"
if ($LASTEXITCODE -ne 0) { Log 'WARN: remote backup failed (still trying upload)' }

& scp -i $Key -o StrictHostKeyChecking=no -o BatchMode=yes $OutFile "${Server}:$RemoteDir/price_snapshot.json"
if ($LASTEXITCODE -ne 0) { Log "ERROR: scp upload failed exit=$LASTEXITCODE"; exit 3 }

# 4) verify live API
Log '[4/4] verify live API'
try {
  $r = Invoke-WebRequest -Uri 'https://agi-goldsum-crm.duckdns.org/api/metal-prices?cur=USD' -UseBasicParsing -TimeoutSec 30
  $j = $r.Content | ConvertFrom-Json
  $last = $j.labels[-1]
  $updated = $j._updated
  Log ('[4/4] live labels_last={0}  _updated={1}' -f $last, $updated)
  $want = Get-Date -Format 'yyyy-MM'
  if ($last -ne $want) {
    Log ('WARN: live newest month {0} != current month {1} (source may not publish this month yet)' -f $last, $want)
  } else {
    Log 'OK: dashboard price data is up to current month'
  }
  $status = @{ at = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'); newest = $last; expected = $want; size = $size; ok = ($last -eq $want) }
  $status | ConvertTo-Json | Set-Content -Path (Join-Path $OutDir 'last_refresh.json') -Encoding utf8
} catch {
  Log ('ERROR: verify failed ' + $_.Exception.Message)
  exit 4
}

Log '========== refresh_prices done =========='
exit 0
